kIn = input(7, "K Neighbors", 1, 15, 1)
featLen = input(20, "Feature Bars", 5, 40, 1)
searchLen = input(200, "Searchback", 30, 400, 5)
mThresh = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
gThresh = input(0.45, "Disagreement Max", 0.1, 1.0, 0.01)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Feature per bar: normalized returns ───
r = 0.0
if close[1] != 0 {
    r := (close - close[1]) / close[1]
}

// ─── Current window mean / stdev (20 r's) ───
mean0 = 0.0
j0 = 0
while j0 < featLen {
    mean0 := mean0 + r[j0]
    j0 := j0 + 1
}
mean0 := mean0 / featLen

var0 = 0.0
j1 = 0
while j1 < featLen {
    d0 = r[j1] - mean0
    var0 := var0 + d0 * d0
    j1 := j1 + 1
}
var0 := var0 / featLen
sd0 = sqrt(var0)
if sd0 < 0.0000001 {
    sd0 := 0.0000001
}

// ─── Effective search depth (adapts on short histories) ───
effSearch = bar_index - featLen
if effSearch > searchLen {
    effSearch := searchLen
}
if effSearch < 0 {
    effSearch := 0
}

// ─── 7 best neighbours (scalar top-k, no arrays) ───
bestD0 = 1000000000000.0
bestD1 = 1000000000000.0
bestD2 = 1000000000000.0
bestD3 = 1000000000000.0
bestD4 = 1000000000000.0
bestD5 = 1000000000000.0
bestD6 = 1000000000000.0
bestL0 = 0
bestL1 = 0
bestL2 = 0
bestL3 = 0
bestL4 = 0
bestL5 = 0
bestL6 = 0

i = 1
while i <= effSearch {
    // past window mean
    meanI = 0.0
    j = 0
    while j < featLen {
        meanI := meanI + r[i + j]
        j := j + 1
    }
    meanI := meanI / featLen
    // past window stdev
    varI = 0.0
    j = 0
    while j < featLen {
        dI = r[i + j] - meanI
        varI := varI + dI * dI
        j := j + 1
    }
    varI := varI / featLen
    sdI = sqrt(varI)
    if sdI < 0.0000001 {
        sdI := 0.0000001
    }
    // euclidean distance between normalized vectors
    dist2 = 0.0
    j = 0
    while j < featLen {
        a = (r[j] - mean0) / sd0
        b = (r[i + j] - meanI) / sdI
        dd = a - b
        dist2 := dist2 + dd * dd
        j := j + 1
    }
    dist = sqrt(dist2)
    // label by realized next-bar direction of that past window
    lab = -1
    if close[i - 1] > close[i] {
        lab := 1
    }
    // sorted insert into 7 slots
    if dist < bestD0 {
        bestD6 := bestD5
        bestL6 := bestL5
        bestD5 := bestD4
        bestL5 := bestL4
        bestD4 := bestD3
        bestL4 := bestL3
        bestD3 := bestD2
        bestL3 := bestL2
        bestD2 := bestD1
        bestL2 := bestL1
        bestD1 := bestD0
        bestL1 := bestL0
        bestD0 := dist
        bestL0 := lab
    } else {
        if dist < bestD1 {
            bestD6 := bestD5
            bestL6 := bestL5
            bestD5 := bestD4
            bestL5 := bestL4
            bestD4 := bestD3
            bestL4 := bestL3
            bestD3 := bestD2
            bestL3 := bestL2
            bestD2 := bestD1
            bestL2 := bestL1
            bestD1 := dist
            bestL1 := lab
        } else {
            if dist < bestD2 {
                bestD6 := bestD5
                bestL6 := bestL5
                bestD5 := bestD4
                bestL5 := bestL4
                bestD4 := bestD3
                bestL4 := bestL3
                bestD3 := bestD2
                bestL3 := bestL2
                bestD2 := dist
                bestL2 := lab
            } else {
                if dist < bestD3 {
                    bestD6 := bestD5
                    bestL6 := bestL5
                    bestD5 := bestD4
                    bestL5 := bestL4
                    bestD4 := bestD3
                    bestL4 := bestL3
                    bestD3 := dist
                    bestL3 := lab
                } else {
                    if dist < bestD4 {
                        bestD6 := bestD5
                        bestL6 := bestL5
                        bestD5 := bestD4
                        bestL5 := bestL4
                        bestD4 := dist
                        bestL4 := lab
                    } else {
                        if dist < bestD5 {
                            bestD6 := bestD5
                            bestL6 := bestL5
                            bestD5 := dist
                            bestL5 := lab
                        } else {
                            if dist < bestD6 {
                                bestD6 := dist
                                bestL6 := lab
                            }
                        }
                    }
                }
            }
        }
    }
    i := i + 1
}

// ─── Channel 1: vote margin, Channel 2: disagreement ───
bullCount = 0
bearCount = 0
if bestD0 < 999999999999.0 {
    if bestL0 == 1 { bullCount := bullCount + 1 } else { bearCount := bearCount + 1 }
}
if bestD1 < 999999999999.0 {
    if bestL1 == 1 { bullCount := bullCount + 1 } else { bearCount := bearCount + 1 }
}
if bestD2 < 999999999999.0 {
    if bestL2 == 1 { bullCount := bullCount + 1 } else { bearCount := bearCount + 1 }
}
if bestD3 < 999999999999.0 {
    if bestL3 == 1 { bullCount := bullCount + 1 } else { bearCount := bearCount + 1 }
}
if bestD4 < 999999999999.0 {
    if bestL4 == 1 { bullCount := bullCount + 1 } else { bearCount := bearCount + 1 }
}
if bestD5 < 999999999999.0 {
    if bestL5 == 1 { bullCount := bullCount + 1 } else { bearCount := bearCount + 1 }
}
if bestD6 < 999999999999.0 {
    if bestL6 == 1 { bullCount := bullCount + 1 } else { bearCount := bearCount + 1 }
}

voteMargin = (bullCount - bearCount) / kIn
disagree = 1 - abs(voteMargin)
crisp = 1 - disagree

// ─── Signal rules: both channels must agree ───
ready = effSearch >= kIn
buyCond = voteMargin > mThresh and disagree < gThresh and ready
sellCond = voteMargin < 0 - mThresh and disagree < gThresh and ready
buySig = buyCond and not buyCond[1]
sellSig = sellCond and not sellCond[1]

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "separate")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 0, "separate")
}

// ─── 2D: two independently readable channels ───
plot(voteMargin, "Vote Margin", "#22cc88", 2, "separate")
plot(disagree, "Disagreement", "#ff4477", 1, "separate")
hline(0, "#888888", "separate")

// ─── 3D: crisp = tall pillar, contested = flat slab ───
plot3d(voteMargin, "Vote Margin 3D", "bars3d", "#22cc88", "separate")
plot3d(disagree, "Disagreement 3D", "scatter", "#ff4477", "separate", 1)

rowsCount = input(24, "Rows Count", 10, 48, 1)
vaPct = input(70, "Value Area Percent", 50, 90, 5)
sessLen = input(120, "Session Lookback Bars", 20, 300, 10)
confirmN = input(1, "Breakout Confirmation Closes", 1, 5, 1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

sessHigh = highest(high, sessLen)
sessLow = lowest(low, sessLen)
rng = sessHigh - sessLow
if rng <= 0 {
    rng := close * 0.01
}
rowH = rng / rowsCount
if rowH <= 0 {
    rowH := close * 0.001
}

rowVol = array()
i = 0
while i < rowsCount {
    array.push(rowVol, 0.0)
    i := i + 1
}

k = 0
while k < sessLen {
    bHigh = high[k]
    bLow = low[k]
    bVol = volume[k]
    bRange = bHigh - bLow
    if bRange <= 0 {
        midIdx = floor((bHigh - sessLow) / rowH)
        if midIdx < 0 { midIdx := 0 }
        if midIdx > rowsCount - 1 { midIdx := rowsCount - 1 }
        array.set(rowVol, midIdx, array.get(rowVol, midIdx) + bVol)
    } else {
        r = 0
        while r < rowsCount {
            rLow = sessLow + r * rowH
            rHigh = rLow + rowH
            top = bHigh
            if rHigh < top { top := rHigh }
            bot = bLow
            if rLow > bot { bot := rLow }
            ov = top - bot
            if ov > 0 {
                contrib = bVol * ov / bRange
                array.set(rowVol, r, array.get(rowVol, r) + contrib)
            }
            r := r + 1
        }
    }
    k := k + 1
}

totalVol = array.sum(rowVol)
pocRow = 0
pocVol = array.get(rowVol, 0)
i = 1
while i < rowsCount {
    v = array.get(rowVol, i)
    if v > pocVol {
        pocVol := v
        pocRow := i
    }
    i := i + 1
}
pocPrice = sessLow + (pocRow + 0.5) * rowH

vaLow = pocRow
vaHigh = pocRow
accum = pocVol
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < rowsCount {
    leftVal = 0 - 1.0
    if vaLow > 0 { leftVal := array.get(rowVol, vaLow - 1) }
    rightVal = 0 - 1.0
    if vaHigh < rowsCount - 1 { rightVal := array.get(rowVol, vaHigh + 1) }
    if rightVal >= leftVal and vaHigh < rowsCount - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vahPrice = sessLow + (vaHigh + 1) * rowH
valPrice = sessLow + vaLow * rowH

closeRow = floor((close - sessLow) / rowH)
if closeRow < 0 { closeRow := 0 }
if closeRow > rowsCount - 1 { closeRow := rowsCount - 1 }
volAtPrice = array.get(rowVol, closeRow)
volRatio = 0.0
if pocVol > 0 { volRatio := volAtPrice / pocVol }
terrainPrice = close + volRatio * rng * 0.25
insideVA = close >= valPrice and close <= vahPrice

upOk = true
dnOk = true
j = 0
while j < confirmN {
    cj = close[j]
    vh = vahPrice[j]
    vl = valPrice[j]
    if cj <= vh { upOk := false }
    if cj >= vl { dnOk := false }
    j := j + 1
}
priorClose = close[confirmN]
priorVAH = vahPrice[confirmN]
priorVAL = valPrice[confirmN]
priorInside = priorClose >= priorVAL and priorClose <= priorVAH
buySig = priorInside and upOk
sellSig = priorInside and dnOk

if buySig {
    plotshape(bar_index, low, "Breakout Up", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Breakout Up", "coneup", "#22cc88", 1.0 * markerSize, 1, "3d")
}
if sellSig {
    plotshape(bar_index, high, "Breakdown Dn", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Breakdown Dn", "conedown", "#ff4477", 1.0 * markerSize, 3, "3d")
}
if bar_index % 60 == 0 {
    label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.2, 1, "3d")
}

plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(terrainPrice, "Value Terrain Twin", "#4488ff", 1)
plot(volRatio * 100, "Volume At Price %", "#4488ff", 1, "separate")
plot(pocPrice, "POC 2D Twin", "#ffd43b", 1, "separate")
box.new(bar_index - sessLen, vahPrice, bar_index, valPrice, "#ffd43b", "rgba(255,212,59,0.08)", 1, "VAZONE")
plot3d(terrainPrice, "Value Terrain", "surface", "#4488ff", "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vahPrice, "VAH Level", "line3d", "#22cc88", "3d", 2)

// FIX 1: var lvl = highest(high, 20) froze the level on bar 0 — plain assignment recomputes every bar.
// FIX 2: close[-1] peeked one bar into the future — close reads the current bar with no lookahead.
// FIX 3: plotshape(true, low, "Buy", shape.triangleup, color.green) is Pine syntax — OakScript needs (bar_index, price, title, "style", "#hex").
// FIX 4: RSI in pane="3d" renders as a spiky forest over price — oscillators must use pane="separate" with a 2D twin.
lvlLen = input(20, "Level Length", 1, 100, 1)
rsiLen = input(14, "RSI Length", 2, 50, 1)
osLevel = input(30, "Oversold Level", 10, 50, 1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)
lvl = highest(high, lvlLen)
r = rsi(close, rsiLen)
buySig = close > lvl
osSig = crossover(r, osLevel)
if buySig {
  plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
  plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", markerSize, 0, "separate")
}
if osSig {
  plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
  plotshape_3d(bar_index, low, "OS", "coneup", "#22cc88", markerSize, 0, "separate")
}
plot(lvl, "Breakout Level", "#ffaa00", 1, "stepline")
plot(r, "RSI", "#b48cff", 1, "line")
hline(osLevel, "#22cc88")
plot3d(r, "RSI", "surface", "#b48cff", "separate")

flowSrc = input(100, "Flow PSI Base", 0, 300, 1)
critThresh = input(150, "Critical Threshold", 50, 300, 1)
rotFactor = input(1.0, "Rotation Factor", 0.1, 5.0, 0.1)
maxRings = input(5, "Max Rings", 1, 10, 1)
ringSpeed = input(1.0, "Ring Expansion Speed", 0.1, 5.0, 0.1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

flow_psi = flowSrc + (close - open) * 2.0 + (high - low) * 0.5
spin_speed = flow_psi * rotFactor
overpressure = flow_psi > critThresh
wasOver = overpressure[1]

var discAngle = 0.0
var lockAngle = 0.0
var ringR = 0.0
var actualAngle = 0.0

if overpressure {
    if wasOver {
        ringR := ringR[1] + ringSpeed
        discAngle := discAngle[1]
        lockAngle := lockAngle[1]
        actualAngle := lockAngle[1]
    } else {
        lockAngle := discAngle[1]
        discAngle := discAngle[1]
        ringR := 1.0
        actualAngle := discAngle[1]
    }
} else {
    discAngle := discAngle[1] + spin_speed
    if discAngle >= 360.0 {
        discAngle := discAngle - 360.0
    }
    lockAngle := discAngle
    ringR := 0.0
    actualAngle := discAngle
}

ring1 = ringR
ring2 = ringR - 2.0
ring3 = ringR - 4.0
ring4 = ringR - 6.0
ring5 = ringR - 8.0
labelPrice = high + (high - low) * 0.5 + 5.0

sellSig = crossover(flow_psi, critThresh)
buySig = crossunder(flow_psi, critThresh)
overEnter = overpressure and not wasOver
overExit = not overpressure and wasOver

if sellSig {
    plotshape(bar_index, high, "Overpressure", "triangledown", "#ff4477")
}

if buySig {
    plotshape(bar_index, low, "Reset", "triangleup", "#22cc88")
}

if overEnter {
    plotshape_3d(bar_index, flow_psi, "Disc Locked", "sphere", "#8899aa", markerSize, 0, "separate", 0, actualAngle, 0)
}

if overEnter {
    label3d(bar_index, labelPrice, "OVERPRESSURE", "#ff4477", 2, 6, "separate")
}

if overEnter {
    plotshape_3d(bar_index, flow_psi, "Ring1", "torus", "#ff4477", markerSize + 0.6, 1, "separate", 90, 0, 0)
}

if overEnter {
    if maxRings >= 2 {
        plotshape_3d(bar_index, flow_psi, "Ring2", "torus", "#ff8844", markerSize + 1.2, 2, "separate", 90, 0, 0)
    }
}

if overEnter {
    if maxRings >= 3 {
        plotshape_3d(bar_index, flow_psi, "Ring3", "torus", "#ffcc33", markerSize + 1.8, 3, "separate", 90, 0, 0)
    }
}

if overEnter {
    if maxRings >= 4 {
        plotshape_3d(bar_index, flow_psi, "Ring4", "torus", "#ff8844", markerSize + 2.4, 4, "separate", 90, 0, 0)
    }
}

if overEnter {
    if maxRings >= 5 {
        plotshape_3d(bar_index, flow_psi, "Ring5", "torus", "#ff4477", markerSize + 3.0, 5, "separate", 90, 0, 0)
    }
}

if overExit {
    plotshape_3d(bar_index, flow_psi, "Valve Disc", "sphere", "#22aaff", markerSize, 0, "separate", 0, actualAngle, 0)
}

plot(flow_psi, "Flow PSI", "#22aaff", 2)
plot(actualAngle, "Disc Angle", "#ffcc33", 1)
hline(critThresh, "#ff4477")
plot3d(flow_psi, "Flow PSI", "ribbon", "#22aaff", "separate", 0)
plot3d(actualAngle, "Disc Angle", "trail", "#ffcc33", "separate", 1)
